361→// MermaidDiagram generates a Mermaid state diagram from the transition table.
362→// The diagram is derived by calling Transition() for representative context
363→// variants per phase/event, so it stays in sync with the implementation.
364→func MermaidDiagram() string {
365→	var b strings.Builder
366→	b.WriteString("stateDiagram-v2\n")
367→
368→	// State declarations with descriptions.
369→	b.WriteString("    state \"IDLE\" as idle\n")
370→	b.WriteString("    state \"ACTIVE\" as active\n")
371→	b.WriteString("    state \"ENDED\" as ended\n")
372→	b.WriteString("\n")
373→
374→	// Context variants for GitCommit: rebase, files/no-files.
375→	type contextVariant struct {
376→		label string
377→		ctx   TransitionContext
378→	}
379→
380→	// For each phase/event, generate edges.
381→	for _, phase := range allPhases {
382→		for _, event := range allEvents {
383→			var variants []contextVariant
384→			switch {
385→			case event == EventGitCommit && phase == PhaseEnded:
386→				// HasFilesTouched only affects PhaseEnded transitions;
387→				// other phases produce identical edges for both values.
388→				variants = []contextVariant{
389→					{"[files]", TransitionContext{HasFilesTouched: true}},
390→					{"[no files]", TransitionContext{HasFilesTouched: false}},
391→					{"[rebase]", TransitionContext{IsRebaseInProgress: true}},
392→				}
393→			case event == EventGitCommit:
394→				variants = []contextVariant{
395→					{"", TransitionContext{}},
396→					{"[rebase]", TransitionContext{IsRebaseInProgress: true}},
397→				}
398→			default:
399→				variants = []contextVariant{
400→					{"", TransitionContext{}},
401→				}
402→			}
403→
404→			for _, v := range variants {
405→				result := Transition(phase, event, v.ctx)
406→
407→				// Build edge label.
408→				label := event.String()
409→				if v.label != "" {
410→					label += " " + v.label
411→				}
412→				if len(result.Actions) > 0 {
413→					actionNames := make([]string, 0, len(result.Actions))
414→					for _, a := range result.Actions {
415→						actionNames = append(actionNames, a.String())
416→					}
417→					label += " / " + strings.Join(actionNames, ", ")
418→				}
419→
420→				from := string(phase)
421→				to := string(result.NewPhase)
422→
423→				fmt.Fprintf(&b, "    %s --> %s : %s\n", from, to, label)
424→			}
425→		}
426→	}
427→
428→	return b.String()
429→}
