 44→// hooksDirCache caches the hooks directory to avoid repeated git subprocess spawns.
 45→// Keyed by current working directory to handle directory changes.
 46→var (
 47→	hooksDirMu       sync.RWMutex
 48→	hooksDirCache    string
 49→	hooksDirCacheDir string
