 92→// getGitDirInPath returns the git directory for a repository at the given path.
 93→// It delegates to `git rev-parse --git-dir` to leverage git's own validation.
 94→func getGitDirInPath(ctx context.Context, dir string) (string, error) {
 95→	cmd := exec.CommandContext(ctx, "git", "rev-parse", "--git-dir")
 96→	cmd.Dir = dir
 97→	output, err := cmd.Output()
 98→	if err != nil {
 99→		return "", errors.New("not a git repository")
100→	}
101→
102→	gitDir := strings.TrimSpace(string(output))
103→
104→	// git rev-parse --git-dir returns relative paths from the working directory,
105→	// so we need to make it absolute if it isn't already
106→	if !filepath.IsAbs(gitDir) {
107→		gitDir = filepath.Join(dir, gitDir)
108→	}
109→
110→	return filepath.Clean(gitDir), nil
111→}
