270→// writeHookFile writes a hook file if it doesn't exist or has different content.
271→// Returns true if the file was written, false if it already had the same content.
272→func writeHookFile(path, content string) (bool, error) {
273→	// Check if file already exists with same content
274→	existing, err := os.ReadFile(path) //nolint:gosec // path is controlled
275→	if err == nil && string(existing) == content {
276→		return false, nil // Already up to date
277→	}
278→
279→	// Git hooks must be executable (0o755)
280→	if err := os.WriteFile(path, []byte(content), 0o755); err != nil { //nolint:gosec // Git hooks require executable permissions
281→		return false, fmt.Errorf("failed to write hook file %s: %w", path, err)
282→	}
283→	return true, nil
284→}
