286→// RemoveGitHook removes all Entire CLI git hooks from the repository.
287→// If a .pre-entire backup exists, it is restored.
288→// Returns the number of hooks removed.
289→func RemoveGitHook(ctx context.Context) (int, error) {
290→	hooksDir, err := GetHooksDir(ctx)
291→	if err != nil {
292→		return 0, err
293→	}
294→
295→	removed := 0
296→	var removeErrors []string
297→
298→	for _, hook := range gitHookNames {
299→		hookPath := filepath.Join(hooksDir, hook)
300→		backupPath := hookPath + backupSuffix
301→
302→		// Remove the hook if it contains our marker
303→		data, err := os.ReadFile(hookPath) //nolint:gosec // path is controlled
304→		hookIsOurs := err == nil && strings.Contains(string(data), entireHookMarker)
305→		hookExists := err == nil
306→
307→		if hookIsOurs {
308→			if err := os.Remove(hookPath); err != nil {
309→				removeErrors = append(removeErrors, fmt.Sprintf("%s: %v", hook, err))
310→				continue
311→			}
312→			removed++
313→		}
314→
315→		// Restore .pre-entire backup if it exists
316→		if fileExists(backupPath) {
317→			if hookExists && !hookIsOurs {
318→				// A non-Entire hook is present — don't overwrite it with the backup
319→				fmt.Fprintf(os.Stderr, "[entire] Warning: %s was modified since install; backup %s%s left in place\n", hook, hook, backupSuffix)
320→			} else {
321→				if err := os.Rename(backupPath, hookPath); err != nil {
322→					removeErrors = append(removeErrors, fmt.Sprintf("restore %s%s: %v", hook, backupSuffix, err))
323→				}
324→			}
325→		}
326→	}
327→
328→	if len(removeErrors) > 0 {
329→		return removed, fmt.Errorf("failed to remove hooks: %s", strings.Join(removeErrors, "; "))
330→	}
331→	return removed, nil
332→}
