345→// hookCmdPrefix returns the command prefix for hook scripts and warning messages.
346→// Returns "go run ./cmd/entire/main.go" when local_dev is enabled.
347→// When absolutePath is true, resolves the full binary path via os.Executable()
348→// and returns an error if resolution fails. This is needed for GUI git clients
349→// (Xcode, Tower, etc.) that don't source shell profiles.
350→func hookCmdPrefix(localDev, absolutePath bool) (string, error) {
351→	if localDev {
352→		return "go run ./cmd/entire/main.go", nil
353→	}
354→	if absolutePath {
355→		exe, err := os.Executable()
356→		if err != nil {
357→			return "", fmt.Errorf("--absolute-git-hook-path: failed to resolve binary path: %w", err)
358→		}
359→		resolved, err := filepath.EvalSymlinks(exe)
360→		if err != nil {
361→			return "", fmt.Errorf("--absolute-git-hook-path: failed to resolve symlinks for %s: %w", exe, err)
362→		}
363→		return shellQuote(resolved), nil
364→	}
365→	return "entire", nil
366→}
367→
368→// shellQuote wraps a string in single quotes for safe use in #!/bin/sh scripts.
369→// Handles paths containing spaces, apostrophes, or other shell metacharacters
370→// (e.g., /Users/John O'Brien/bin/entire).
371→func shellQuote(s string) string {
372→	return "'" + strings.ReplaceAll(s, "'", "'\\''") + "'"
373→}
