225→// hasUserContent checks if the message has any content besides comments and our trailer.
226→func hasUserContent(message string) bool {
227→	trailerPrefix := trailers.CheckpointTrailerKey + ":"
228→	for _, line := range strings.Split(message, "\n") {
229→		trimmed := strings.TrimSpace(line)
230→		// Skip empty lines
231→		if trimmed == "" {
232→			continue
233→		}
234→		// Skip comment lines
235→		if strings.HasPrefix(trimmed, "#") {
236→			continue
237→		}
238→		// Skip our trailer line
239→		if strings.HasPrefix(trimmed, trailerPrefix) {
240→			continue
241→		}
242→		// Found user content
243→		return true
244→	}
245→	return false
246→}
