248→// stripCheckpointTrailer removes the Entire-Checkpoint trailer line from the message.
249→func stripCheckpointTrailer(message string) string {
250→	trailerPrefix := trailers.CheckpointTrailerKey + ":"
251→	var result []string
252→	for _, line := range strings.Split(message, "\n") {
253→		if !strings.HasPrefix(strings.TrimSpace(line), trailerPrefix) {
254→			result = append(result, line)
255→		}
256→	}
257→	return strings.Join(result, "\n")
258→}
