270→// TestUserPromptSubmit_ReinstallsOverwrittenHooks verifies that EnsureSetup is called
271→// during user-prompt-submit (start of turn) and reinstalls hooks that were overwritten
272→// by third-party tools like lefthook. This ensures hooks are in place before any
273→// mid-turn commits the agent might make.
274→func TestUserPromptSubmit_ReinstallsOverwrittenHooks(t *testing.T) {
275→	t.Parallel()
276→	env := NewRepoWithCommit(t)
277→	hooksDir := filepath.Join(env.RepoDir, ".git", "hooks")
278→	hookNames := strategy.ManagedGitHookNames()
279→
280→	// Step 1: First user-prompt-submit installs hooks via EnsureSetup
281→	session := env.NewSession()
282→	err := env.SimulateUserPromptSubmit(session.ID)
283→	if err != nil {
284→		t.Fatalf("First SimulateUserPromptSubmit failed: %v", err)
285→	}
286→
287→	// Verify hooks are now installed
288→	if !strategy.IsGitHookInstalledInDir(context.Background(), env.RepoDir) {
289→		t.Fatal("hooks should be installed after first SimulateUserPromptSubmit")
290→	}
291→
292→	// Step 2: Overwrite hooks with third-party content (simulating lefthook, husky, etc.)
293→	for _, hookName := range hookNames {
294→		hookPath := filepath.Join(hooksDir, hookName)
295→		thirdPartyContent := "#!/bin/sh\n# Third-party hook manager\necho 'Running third-party hook'\n"
296→		if err := os.WriteFile(hookPath, []byte(thirdPartyContent), 0o755); err != nil {
297→			t.Fatalf("failed to overwrite hook %s: %v", hookName, err)
298→		}
299→	}
300→
301→	// Step 3: Verify hooks are no longer Entire hooks
302→	if strategy.IsGitHookInstalledInDir(context.Background(), env.RepoDir) {
303→		t.Fatal("hooks should NOT be detected as Entire hooks after overwrite")
304→	}
305→
306→	// Step 4: Second user-prompt-submit should reinstall hooks
307→	err = env.SimulateUserPromptSubmit(session.ID)
308→	if err != nil {
309→		t.Fatalf("Second SimulateUserPromptSubmit failed: %v", err)
310→	}
311→
312→	// Step 5: Verify hooks are reinstalled
313→	if !strategy.IsGitHookInstalledInDir(context.Background(), env.RepoDir) {
314→		t.Error("hooks should be reinstalled after second SimulateUserPromptSubmit")
315→	}
316→
317→	// Step 6: Verify the hooks chain to original hooks (backup should exist)
318→	for _, hookName := range hookNames {
319→		backupPath := filepath.Join(hooksDir, hookName+".pre-entire")
320→		if _, err := os.Stat(backupPath); os.IsNotExist(err) {
321→			t.Errorf("backup hook %s.pre-entire should exist", hookName)
322→		}
323→	}
324→}
